CREATE TABLE location_changes (
  id TEXT PRIMARY KEY,
  group_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  farm_code TEXT NOT NULL,
  license_value TEXT NOT NULL,
  tag TEXT,
  item_id TEXT,
  label TEXT NOT NULL,
  from_location TEXT,
  to_location TEXT NOT NULL,
  move_date TEXT NOT NULL,
  created_at TEXT NOT NULL,
  created_by TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT,
  deleted_at TEXT,
  deleted_by TEXT,
  delete_reason TEXT
);

